// Every engine against the Nunjucks parity corpus: 149 snippets rendered by
// Nunjucks 3.2.4 in Anvil 0.1.6's exact environment
// (test/fixtures/nunjucks-parity.json, regenerated by
// tool/nunjucks_oracle.js from tool/parity_cases.js).
//
// The expected non-matching sets are pinned, so a change in either engine
// shows up here and FINDINGS.md stays honest. These are accepted, documented
// differences, not equality assertions.
import 'package:template_engine/template_engine.dart';
import 'package:test/test.dart';

import 'support/fixtures.dart';

void main() {
  final corpus = jsonFixture('nunjucks-parity.json');
  final context = fullContext();

  Map<String, Verdict> nonMatches(List<CaseResult> results) => {
    for (final r in results)
      if (r.verdict != Verdict.match) r.name: r.verdict,
  };

  test('corpus size', () => expect(corpus.length, 149));

  group('option 2: purpose-built subset renderer', () {
    final results = scoreCorpus(corpus, context, renderAnvilTemplate);

    test('every guide.* and edge.* case matches Nunjucks', () {
      final misses = results
          .where((r) => !r.name.startsWith('idiom.'))
          .where((r) => r.verdict != Verdict.match);
      expect(misses.map((r) => '${r.name}: ${r.detail}'), isEmpty);
    });

    test('it never renders different output: each miss is a clean '
        'parse-time "unsupported" rejection', () {
      for (final MapEntry(:key, :value) in nonMatches(results).entries) {
        expect(value, Verdict.engineRejects, reason: key);
        final source =
            (corpus[key] as Map<String, Object?>)['source'] as String;
        expect(
          AnvilTemplate.check(source)?.kind,
          TemplateErrorKind.unsupported,
          reason: '$key is rejected by the parser, before any rendering',
        );
      }
    });

    test('the unsupported set is exactly the documented one', () {
      printOnFailure(summarise(results));
      expect(nonMatches(results).keys.toSet(), {
        'idiom.sort',
        'idiom.round_int_float',
        'idiom.sum',
        'idiom.batch_slice',
        'idiom.selectattr',
        'idiom.select_reject',
        'idiom.groupby',
        'idiom.dictsort',
        'idiom.list_filter',
        'idiom.string_filter',
        'idiom.text_filters',
        'idiom.html_filters',
        'idiom.is_tests',
        'idiom.set_block',
        'idiom.filter_block',
        'idiom.raw_block',
        'idiom.macro',
        'idiom.range',
        'idiom.cycler_joiner',
        'idiom.method_call',
      });
    });
  });

  group('option 1: jinja 0.7.2, Anvil-tuned', () {
    final results = scoreCorpus(corpus, context, JinjaRenderer().render);

    test('documented differences from Nunjucks', () {
      printOnFailure(summarise(results));
      expect(nonMatches(results), {
        // Silently different output (the dangerous category).
        'guide.crlf_kept': Verdict.outputDiffers, // CRLF normalised to LF
        'guide.string_escapes': Verdict.outputDiffers, // \" \' \t \n kept raw
        'idiom.reverse': Verdict.outputDiffers, // string reverse -> (c, b, a)
        'idiom.set_accumulate_in_loop': Verdict.outputDiffers, // loop scope
        'idiom.truthy_empty_list': Verdict.outputDiffers, // [] is falsy
        'idiom.truthy_empty_object': Verdict.outputDiffers, // {} is falsy
        'idiom.and_returns_operand': Verdict.outputDiffers, // [] or 'x'
        'edge.concat_undefined': Verdict.outputDiffers, // anull vs aundefined
        'edge.for_object_single_target': Verdict.outputDiffers, // MapEntry
        'edge.big_numbers': Verdict.outputDiffers, // int64 wrap-around
        'edge.remainder_sign': Verdict.outputDiffers, // Dart % vs JS %
        'edge.json_escapes': Verdict.outputDiffers, // literal escapes again
        'edge.json_indent_variants': Verdict.outputDiffers, // '\t' literal
        'edge.js_precedence_not': Verdict.outputDiffers, // not a == b
        'edge.js_precedence_compare': Verdict.outputDiffers, // a == b < c
        // Errors where Nunjucks rendered.
        'idiom.inline_if_no_else': Verdict.engineRejects,
        'idiom.plus_strings': Verdict.engineRejects,
        'idiom.join': Verdict.engineRejects, // no attribute argument
        'idiom.sort': Verdict.engineRejects,
        'idiom.round_int_float': Verdict.engineRejects,
        'idiom.sum': Verdict.engineRejects,
        'idiom.selectattr': Verdict.engineRejects,
        'idiom.select_reject': Verdict.engineRejects,
        'idiom.groupby': Verdict.engineRejects,
        'idiom.text_filters': Verdict.engineRejects,
        'idiom.html_filters': Verdict.engineRejects,
        'idiom.set_in_loop_persists_iterations': Verdict.engineRejects,
        'idiom.elseif_keyword': Verdict.engineRejects,
        'idiom.dict_literal': Verdict.engineRejects, // bare-name keys
        'idiom.loose_equality': Verdict.engineRejects, // no === / !==
        'idiom.string_compare': Verdict.engineRejects,
        'idiom.cycler_joiner': Verdict.engineRejects,
        'idiom.method_call': Verdict.engineRejects,
        'edge.plus_undefined': Verdict.engineRejects,
        'edge.filter_on_undefined': Verdict.engineRejects,
        'edge.for_undefined': Verdict.engineRejects,
        'edge.for_undefined_else': Verdict.engineRejects,
        'edge.for_null': Verdict.engineRejects,
        'edge.compare_undefined': Verdict.engineRejects,
        'edge.js_precedence_concat': Verdict.engineRejects,
        // Renders where Nunjucks threw.
        'idiom.map_filter_absent': Verdict.engineAccepts,
        'edge.default_null_no_bool': Verdict.engineAccepts,
        'edge.json_undefined': Verdict.engineAccepts,
        'edge.float_literal_exponent': Verdict.engineAccepts,
      });
    });

    test('jinja-level undefined (throwOnReference) breaks documented '
        'idioms such as {% if missing %}', () {
      final strict = scoreCorpus(
        corpus,
        context,
        JinjaRenderer(undefinedMode: JinjaUndefinedMode.throwOnReference)
            .render,
      );
      final guideMisses = {
        for (final r in strict)
          if (r.name.startsWith('guide.') && r.verdict != Verdict.match) r.name,
      };
      expect(guideMisses, containsAll(['guide.undefined_in_if_ok']));
      // `none` is not a literal in jinja.dart (only `null`), so it also
      // resolves as an unknown name.
      expect(guideMisses, contains('guide.none_literal_falsy'));
    });
  });
}
